from itertools import product

# Partitions are decreasing tuples of positive integers.
def partitions_of(n, max_part, max_len, cap=None):
    if cap is None:
        cap = max_part
    if n == 0:
        yield ()
        return
    if max_len == 0:
        return
    for a in range(min(cap, max_part, n), 0, -1):
        for tail in partitions_of(n-a, max_part, max_len-1, a):
            yield (a,) + tail

def pad(lam, length):
    return lam + (0,) * (length-len(lam))

def in_interval(lam, i, j):
    # i^j subseteq lam subseteq (i+1)^(j+1)
    a = pad(lam, j+1)
    return len(lam) <= j+1 and all(a[t] >= i for t in range(j)) and all(a[t] <= i+1 for t in range(j+1))

def columns(degree, i, j):
    return sorted(lam for lam in partitions_of(degree, i+1, j+1) if in_interval(lam, i, j))

def contains(mu, lam):
    L = max(len(mu), len(lam))
    return all(pad(mu, L)[t] >= pad(lam, L)[t] for t in range(L))

def pieri_h1(lam, target_columns):
    return sorted(mu for mu in target_columns if contains(mu, lam))

def P(i, j, x, y):
    return (i+1,)*x + (i,)*(j-x) + (() if y == 0 else (y,))

def det(A):
    # Bareiss exact integer determinant.
    A = [list(row) for row in A]
    n = len(A)
    if n == 0:
        return 1
    sign, prev = 1, 1
    for k in range(n-1):
        if A[k][k] == 0:
            swap = next((r for r in range(k+1, n) if A[r][k] != 0), None)
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            sign *= -1
        pivot = A[k][k]
        for r in range(k+1, n):
            for c in range(k+1, n):
                A[r][c] = (A[r][c]*pivot - A[r][k]*A[k][c]) // prev
        prev = pivot
        for r in range(k+1, n):
            A[r][k] = 0
    return sign*A[-1][-1]

pairs = degree_cases = column_checks = row_checks = sign_checks = minor_checks = 0
for i, j in product(range(1, 7), repeat=2):
    pairs += 1
    d, b = i*j, min(i, j)
    for k in range(b+1):
        degree_cases += 1
        actual = columns(d+k, i, j)
        expected = sorted(P(i, j, x, k-x) for x in range(k+1))
        assert actual == expected, ('columns', i, j, k, actual, expected)
        column_checks += 1
        # The endpoints are Y_k=P_{0,k}, X_k=P_{k,0}; the row relations
        # enforce [P_{x,k-x}]=(-1)^x[P_{0,k}].
        assert ((-1)**k) * ((-1)**k) == 1
        sign_checks += 1
        if k:
            previous = columns(d+k-1, i, j)
            expected_rows = []
            for x in range(k):
                source = P(i, j, x, k-1-x)
                target_pair = sorted([P(i, j, x, k-x), P(i, j, x+1, k-1-x)])
                got = pieri_h1(source, actual)
                assert got == target_pair, ('h1', i, j, k, source, got, target_pair)
                expected_rows.append((x, x+1))
                row_checks += 1
            # Complete row-index set is exactly the full previous column set.
            assert previous == sorted(P(i, j, x, k-1-x) for x in range(k))
            # Incidence matrix has rows C_x+C_{x+1}; each endpoint deletion is unimodular.
            R = [[int(c == x or c == x+1) for c in range(k+1)] for x in range(k)]
            left_deleted = [[row[c] for c in range(1, k+1)] for row in R]
            right_deleted = [[row[c] for c in range(0, k)] for row in R]
            assert det(left_deleted) == 1 and det(right_deleted) == 1, ('minors', i, j, k, R)
            minor_checks += 2

print('INPUTS: i,j in {1,...,6}; k in {0,...,min(i,j)}')
print('PARAMETER_PAIRS:', pairs)
print('DEGREE_CASES:', degree_cases)
print('INTERVAL_COLUMN_CHECKS:', column_checks)
print('COMPLETE_H1_PIERI_ROW_CHECKS:', row_checks)
print('ENDPOINT_SIGN_CHECKS:', sign_checks)
print('UNIT_MINOR_CHECKS:', minor_checks)
print('IDENTITIES: [P_{x,k-x}]=(-1)^x[P_{0,k}], [X_k]=(-1)^k[Y_k], [Y_k]=(-1)^k[X_k]')
print('RESULT: PASS')
